export const BRAIN_SEARCHARCHIVE_COMMAND_DESCRIPTION = "Search Brain memory when the user asks to recall prior sessions, past decisions, archived context, previous files, or something already discussed. Do not use for fresh web search or current file/project work." as const;
export const BRAIN_RENAME_SESSION_COMMAND_DESCRIPTION = "Rename the current chat session with exactly one standalone Brain-owned compact line /\\\"nomduchat\\\"_renamechat_ after identifying the first user message subject. The app uses the quoted nomduchat field as the sidebar title. The event is internal: never merge it with visible prose, never echo this line in the user-visible answer, and never describe the rename. Use 2-5 natural words, like Codex or Claude; avoid copying the prompt or using only a proper noun." as const;
export const BRAIN_WEBSEARCH_COMMAND_DESCRIPTION = "Use /websearch_ when the user needs current source-backed web research, URL discovery, citation verification, market/tool/library comparisons, recent docs, prices, laws, releases, papers, news, or URLs to feed into /scrapers_. This CodeAct asks the runtime to call hosted OpenAI and/or Claude web-search tools, returning a compact WEBSEARCH_RESULT with the synthesized answer, provider trace, searched queries, ranked URLs, titles, citation spans, snippets/page ages when available, confidence and suggested follow-up scrape URLs. It does not return raw HTML, full page text or media files. After WEBSEARCH_RESULT, the agent should continue the existing loop-stream by emitting /scrapers_ with the selected URLs whenever clean Markdown, images, links, artifacts, durable evidence or structured extraction are needed. Prefer /websearch_ over /googleweb_ for answers that require sources; use /googleweb_ only for visual/manual browser navigation. Respect source attribution, privacy, paywalls, robots/site terms and bounded search budgets." as const;
export const BRAIN_GOOGLEWEB_COMMAND_DESCRIPTION = "Open contained WebExplorer on a generic Google search when the user wants to visually browse or manually inspect web results. Prefer /websearch_ when the assistant must answer with cited sources, discover URLs, rank sources, verify current information or feed /scrapers_. Do not use for Gmail, Airbnb/travel lodging, image generation/editing, or local workspace work." as const;
export const BRAIN_SCRAPERS_COMMAND_DESCRIPTION = "Use /scrapers_ when the user needs production-grade web collection from one or more URLs: structured fields, clean RAG-ready Markdown, links, image/media URLs, optional screenshots/PDF/MHTML/download artifacts, and compact provenance. This Brain route fans out to Scrapling MCP and Crawl4AI MCP in parallel, then returns one merged manifest. Scrapling should handle selectors, attributes, adaptive/dynamic/stealth/session fetches and screenshots; Crawl4AI should handle clean/fit Markdown, chunks, citations, links, media metadata and archival artifacts. Prefer this over choosing only /scrapling_mcp_ when the result should feed Brain memory, RAG, agents, research notes, comparison, monitoring or downstream structured analysis. Use /scrapling_mcp_ directly for a pure low-level selector/session/screenshot operation. Respect robots.txt, site terms, rate limits and privacy; use stealth or anti-bot modes only for authorized targets or user-approved public-data collection. Do not use for Gmail, Airbnb travel search, Maps/geography routing, local files, image generation/editing, or generic Google search." as const;
export const BRAIN_SCRAPLING_MCP_COMMAND_DESCRIPTION = "Use Scrapling MCP for targeted web extraction when the user needs structured page data, bulk URL scraping, dynamic/JavaScript content, screenshots, persistent sessions, adaptive selectors, or compact provenance instead of full raw HTML. Prefer CSS/XPath selectors and manifest-sized results. Respect robots.txt, site terms, rate limits and privacy; use stealth or anti-bot modes only for authorized targets or user-approved public-data collection. Do not use for Gmail, Airbnb travel search, image work, local filesystem work, or generic search that belongs to /googleweb_." as const;
export const BRAIN_MAPS_COMMAND_DESCRIPTION = "Open contained WebExplorer on Google Earth for any detected geographic place. For geography alone, Maps is the only WebExplorer page. For geography plus travel/vacation/stay intent, open Maps first and Airbnb next. Prefer over /sciencebrain_ and /googleweb_ for ordinary geographic context; use Brain home city when no target is specified. Do not read device location silently; current-location use requires explicit user permission." as const;
export const BRAIN_GMAIL_COMMAND_DESCRIPTION = "Use Gmail for mail tasks: open mailbox, search messages, inspect, summarize, draft, or prepare replies. The LLM writes a natural sentence first; never send email automatically and do not use /googleweb_ for Gmail." as const;
export const BRAIN_GMAIL_COM_COMMAND_DESCRIPTION = "Open the Gmail sign-in/mail entry URL directly in split-screen WebExplorer when the user asks to access or open Gmail. Use only for navigation to Gmail, not for generic mail reasoning or web search." as const;
export const BRAIN_AIRBNB_COMMAND_DESCRIPTION = "Use Airbnb after /maps_ when a geographic place is detected together with travel/vacation/stay language: voyage, vacances, partir, visiter, tourisme, sejour, destination, dates, guests, lodging, accommodation, hotel-like stay, home/apartment rental, vacation rental, booking, budget for stays, or short-term stay search. Do not use for city facts, local weather, geography, maps, or routes without travel/vacation/stay intent." as const;
export const BRAIN_NEWIMAGE_COMMAND_DESCRIPTION = "Generate a brand-new image from a text prompt: draw, create, render, imagine, make a logo/poster/scene/asset. Do not use /workspace_; no local project folder is required." as const;
export const BRAIN_EDITIMAGE_COMMAND_DESCRIPTION = "Edit an existing image attached, selected, or visible in the conversation: retouch, remove/add/replace elements, change colors/background/style, crop, upscale, or transform. Prefer over /workspace_; do not answer with an external-tool prompt." as const;
export const BRAIN_QUESTIONNAIRE_COMMAND_DESCRIPTION = "Open a paginated questionnaire above the chat composer when the LLM needs multiple clarifying questions. Use after any required Brain segment switch; never use before /sciencebrain_ or /codingbrain_ while the active Brain is general and the request is specialized. Put each page question in q1, q2, q3... and provide exactly three choices with q1_options, q2_options..." as const;
export const BRAIN_SCIENCE_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to science, engineering, mathematics, biology, chemistry, physics, cryptography, formal analysis, physical product design, electronics, mechanics, robotics, CAD/3D, Banger, Monster, /newcompute_ or future Banger 3D work. Physical product/prototype conception is engineering by default. Activate /sciencebrain_ before questionnaire or specialized answer; after activation, use the injected science brain catalog." as const;
export const BRAIN_CODING_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to software engineering, coding, websites, applications, repositories, debugging, refactoring, tests, architecture, scripts, Rust/TypeScript/Electron, APIs, build systems, or developer tooling. Activate /codingbrain_ before the specialized answer; do not paste implementation code in the same Brain-switch message. After activation, continue in loop-stream mode with the injected coding brain catalog and local action tools." as const;
export const BRAIN_NEWBRAIN_COMMAND_DESCRIPTION = "Create a new specialized Brain scope for a durable domain such as marketing, trading, immobilier, science-notes or another recurring work area. Use only after the LLM has reasoned that repeated lessons, rules, skills, tasks or CodeAct drafts would pollute the General Brain or unrelated sessions if stored globally. The General Brain remains immutable; this command proposes or creates a separate named Brain where future domain-specific lessons can be stored and injected only when relevant. The LLM chooses the domain, title, purpose, activation triggers, initial lesson/rule/skill/task/CodeAct categories and compact token budget; the host only records the explicit fields and must not semantically infer the domain." as const;
export const BRAIN_MODIFY_NAMED_BRAIN_COMMAND_DESCRIPTION = "Modify an existing specialized Brain named in the command form /modify\\\"<brain_name>\\\"brain_. Use when the LLM has a user-confirmed or strong candidate learning that belongs to that named Brain: observed error converted into replacement rule, conduct rule, reusable skill, follow-up task or CodeAct draft. Do not use to mutate the immutable General Brain. The LLM supplies the brain_name, entry kind, evidence/observation, replacement rule when an error is being fixed, trigger, exceptions and compact content; the host only validates, stores and reinjects the explicit update." as const;
export const BRAIN_WORKSPACE_COMMAND_DESCRIPTION = "Ask the user to choose a local project/workspace folder only for coding, repository, filesystem, build, script, or project-file work. Never use for web, Gmail, Airbnb, Brain memory, image generation, or image editing." as const;
export const BRAIN_CAPABILITIES_COMMAND_DESCRIPTION = "Discover the local action atlas when a task may involve the computer, files, apps, browser, documents, code, Git, cloud CLIs, virtualization, Windows settings, packages or automation and the exact local tool route is not already obvious. Executable form: emit AGENT_ACTION_JSON {\\\"action\\\":\\\"capabilities\\\",\\\"scope\\\":\\\"all|workspace|computer|coding|browser|documents|windows|cloud|automation\\\",\\\"query\\\":\\\"short task/topic\\\",\\\"maxResults\\\":40}. This is read-only and returns available actions, risky/blocked/planned boundaries, fallback routes and proof hashes. Use in General, Science and Coding Brain before guessing or answering verbally." as const;
export const BRAIN_CODING_LIVE_PREVIEW_COMMAND_DESCRIPTION = "Open the live coding preview canvas for a visual coding artifact that already exists on disk. Use only while Coding Brain is active, only after creating or modifying a real local HTML/CSS/JS/React/Vite visual file with AGENT_ACTION_JSON and verifying the absolute file path. Immediately before this CodeAct, write one short natural paragraph explaining that the visual preview is being opened in the conversation so the user can watch the result. Required slot: path=\\\"absolute-local-file\\\". Optional slot: kind=\\\"html|react|vite\\\". Never use for backend-only scripts, prose-only snippets, or unverified code blocks." as const;
export const BRAIN_NEWCOMPUTE_COMMAND_DESCRIPTION = "Start a new typed Monster compute when the user needs heavy/local math, simulation, numeric analysis, tensors, optimization, batch calculation, or verifiable compute artifacts rather than a normal prose answer." as const;
export const BRAIN_SELECTCOMPUTE_COMMAND_DESCRIPTION = "Reuse a saved compute from the Brain compute library when the user wants to rerun, adapt, compare, or continue a previous/saved compute instead of defining a new one." as const;
