export const BRAIN_FRONTDESIGN_COMMAND_DESCRIPTION = "Change the app display colors or color palettes when the user asks. Use only for visual color/theme changes, not general coding or image generation." as const;
export const BRAIN_GOOGLE_AGENDA_COMMAND_DESCRIPTION = "Prepare a Google Calendar action when the user asks to create, inspect, or plan calendar events with dates, times, attendees, reminders, or schedule details. Execution stays user-confirmed." as const;
