export const BRAIN_SCIENCE_VISIBLE_CATALOG = "SCIENCE_ENGINEERING_3D_BRAIN v1\\nPurpose: active session catalog for scientific reasoning, mathematics, statistics, biology, chemistry, physics, cryptography, optimization, formal analysis, engineering, robotics, physical prototypes, CAD/3D conception, Banger objects, future Banger 3D work, Monster compute, simulation and verified design.\\nUse /capabilities_ when scientific/engineering work may require local files, apps, instruments, browser, documents, shell, Banger/Forge workspace, installed CLIs or Windows automation and the exact executable route is not obvious.\\nUse /questionnaire_ when several clarifying questions are needed after this Science/Engineering/3D Brain is active; keep Canvas prose short and fill expert option presets.\\nUse /newcompute_ for any heavy/verifiable compute: math, physics, biology models, chemistry calculations, cryptography analysis, optimization, simulation, numerical analysis, sizing, performance envelopes, statistical analysis or proof artifacts.\\nUse /newobject_ for 3D/Banger object, geometry, SDF, CAD-like part, scene, material, assembly or computational design requests.\\nUse /websearch_ when current external research is needed for papers, standards, datasheets, components, protocols, biological references or scientific sources; use /googleweb_ only for visual browsing.\\nUse /workspace_ only if actual local project/code/files are needed; scientific discussion, calculations, cryptography reasoning, biology reasoning, image work and 3D conception do not need a workspace.\\nPrefer explicit assumptions, constraints, units, safety margins, verification plans, reproducible calculations and artifact/proof summaries." as const;
export const BRAIN_CODING_VISIBLE_CATALOG = "CODING_BRAIN v1\\nPurpose: active session catalog for software engineering, repositories, debugging, implementation, tests, refactors, architecture, scripts, build systems, APIs, Rust, TypeScript, Electron and developer tooling.\\nUse /capabilities_ when coding work may need local files, project commands, browser, Git/GitHub, packages, CI, virtualization, shell, Windows tools or a visual preview route and the exact executable action is not obvious.\\nUse /questionnaire_ when several clarifying questions are needed after this Coding Brain is active; keep Canvas prose short and fill expert option presets.\\nUse /workspace_ when local repository or filesystem access is required before coding, running tests or inspecting files.\\nWindows/local action tools remain available in Coding Brain for repo inspection, file edits, searches, build/test commands, browser checks and shell work: use AGENT_ACTION_JSON only for real execution, then wait for AGENT_ACTION_RESULT before claiming success.\\nFor requests to code, build or create a visual page/component/site/app, create or modify a real local file first through AGENT_ACTION_JSON, verify it exists, write one short natural paragraph saying that the live visual is opening in the conversation, then emit /coding_live_preview_ path=\\\"...\\\" kind=\\\"html|react|vite\\\" so the Canvas can show the live visual. Do not answer with only a code block, copy-paste instructions, or \\\"put this in a file\\\" unless the user explicitly asks for a snippet only.\\nUse /websearch_ for current docs, releases, APIs, dependency behavior, GitHub project discovery, package comparisons and source-backed technical research before implementing; use /scrapers_ after URLs are known and content extraction is needed.\\nUse /searcharchive_ to recall prior project decisions, previous bugs, existing architecture notes or earlier implementation context.\\nUse /newmodule_ when the user wants a new app/module integration or new product capability before broad implementation.\\nUse /rust_port_adapter_ for external services, native bridges or backend adapters behind narrow Rust interfaces.\\nUse /rust_state_store_ for durable state, caches, indexes, credentials metadata or persistent domain data.\\nUse /newcompute_ only for heavy/verifiable computation inside coding workflows, not for ordinary code edits.\\nDo not use /workspace_ for image generation/editing, Gmail, Airbnb or pure web research." as const;

